use super::*;

/// 📤️ Denied atomic writes leave exact original buffers unchanged; one funded authored corner accounts for every emitted byte.
#[test]
fn original_mesh_tessellation_corner_emission_prices_exact_atomic_output(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::{retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::controlled::ControlledRetirement};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧩️tessellation/🎟️owners.json")).unwrap();
    for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
        let(mut job,source)=observe(||{let mut job=MeshTessellationJob::new(super::tessellation_metadata_tests::authored_source(&law));while !job.buffer_reservation_complete(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:job.next_buffer_capacity_byte_demand(0).unwrap(),maximum_release_bytes:0,maximum_depth:job.next_buffer_depth_demand().unwrap()};assert!(job.reserve_buffer_step(grant).unwrap().progress().fits(grant));}while !job.metadata_capture_complete(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:job.next_metadata_depth_demand().unwrap()};assert!(job.capture_metadata_step(grant).unwrap().progress().fits(grant));}while job.phase!=7{job.advance().unwrap();}job});
        let original=job.mesh.vertices.as_ptr();let grant=RetainedCloneGrant {maximum_items:law["cornerEmission"]["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:law["cornerEmission"]["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:job.next_corner_capacity_byte_demand(0,56).unwrap(),maximum_release_bytes:job.next_corner_release_byte_demand(0).unwrap(),maximum_depth:job.next_corner_depth_demand(0).unwrap()};assert_eq!(job.next_corner_copy_byte_demand(0).unwrap(),grant.maximum_copy_bytes);assert_eq!(grant.maximum_capacity_bytes,0);assert_eq!(grant.maximum_release_bytes,0);
        let out=job.output.as_ref().unwrap();let pointers=(out.positions.as_ptr(),out.normals.as_ptr(),out.uvs.as_ptr(),out.colors.as_ptr(),out.vertex_ids.as_ptr(),job.corner_ids.as_ptr());
        for denied in [RetainedCloneGrant {maximum_items:0,..grant},RetainedCloneGrant {maximum_copy_bytes:0,..grant},RetainedCloneGrant {maximum_copy_bytes:1,..grant},RetainedCloneGrant {maximum_copy_bytes:3,..grant},RetainedCloneGrant {maximum_copy_bytes:grant.maximum_copy_bytes-1,..grant},RetainedCloneGrant {maximum_depth:grant.maximum_depth-1,..grant}]{let(step,heap)=observe(||job.emit_corner_step(0,denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(job.corner_receipt.0,RetainedCloneProgress::default());assert_eq!(heap,(0,0));let out=job.output.as_ref().unwrap();assert!(out.positions.is_empty()&&out.normals.is_empty()&&out.colors.is_empty()&&out.uvs.is_empty()&&out.vertex_ids.is_empty()&&job.corner_ids.is_empty());assert_eq!((out.positions.as_ptr(),out.normals.as_ptr(),out.uvs.as_ptr(),out.colors.as_ptr(),out.vertex_ids.as_ptr(),job.corner_ids.as_ptr()),pointers);assert_eq!(job.mesh.vertices.as_ptr(),original);}
        let(step,heap)=observe(||job.emit_corner_step(0,grant).unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),job.corner_receipt.0);assert_eq!(step.progress().copied_items,1);assert_eq!(step.progress().copied_bytes,grant.maximum_copy_bytes);assert!(step.progress().fits(grant));let out=job.output.as_ref().unwrap();assert_eq!(out.positions,serde_json::from_value::<Vec<f32>>(law["cornerEmission"]["position"].clone()).unwrap());assert_eq!(out.normals,serde_json::from_value::<Vec<f32>>(law["cornerEmission"]["normal"].clone()).unwrap());assert_eq!(out.uvs,serde_json::from_value::<Vec<f32>>(law["cornerEmission"]["uv"].clone()).unwrap());assert_eq!(out.colors,serde_json::from_value::<Vec<f32>>(law["cornerEmission"]["color"].clone()).unwrap());assert_eq!(out.vertex_ids.len(),1);assert_eq!(job.corner_ids.len(),1);assert_eq!(job.mesh.vertices.as_ptr(),original);assert_eq!((out.positions.as_ptr(),out.normals.as_ptr(),out.uvs.as_ptr(),out.colors.as_ptr(),out.vertex_ids.as_ptr(),job.corner_ids.as_ptr()),pointers);
        let(mut owner,handoff)=observe(||ControlledRetirement::new(job).unwrap_or_else(|_|panic!("original corner closure unsupported")));assert_eq!(handoff,(0,0));let(mut born,mut freed,mut turns)=(source.0,source.1,0);
        while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(close_copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);}
        assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Mesh atomic corner copied={} underAtomic1and3Refused=true sameSource=true sameBacking=true physical={freed} closeCopy={close_copy} terminalDrop=0",law["cornerEmission"]["copyBytes"]);
    }
}
